<script setup lang="ts">/** 数据管理(新版) */ import { ref, onMounted } from 'vue'; import api from '@/api/index';
const stats = ref({ devices: 0, drones: 0, alarms: 0, airspaces: 0 })
onMounted(async () => { try { const [d1,d2,d3,d4] = await Promise.all([api.get('/devices/stats'),api.get('/drones/basic/stats'),api.get('/alarms/stats'),api.get('/airspace',{params:{page:1,page_size:1}})])
stats.value = { devices: d1.data.result?.total||0, drones: d2.data.result?.total||0, alarms: d3.data.result?.total||0, airspaces: d4.data.result?.total||0 }} catch {} })</script>
<template><div class="page"><div class="page-hdr"><h2>数据管理</h2><p>系统数据总览与管理入口</p></div><div class="page-bd"><div class="stats"><div class="stat"><div class="v">{{stats.devices}}</div><div>设备</div></div><div class="stat"><div class="v">{{stats.drones}}</div><div>无人机</div></div><div class="stat"><div class="v">{{stats.alarms}}</div><div>告警</div></div><div class="stat"><div class="v">{{stats.airspaces}}</div><div>空域</div></div></div></div></div></template>
<style scoped>.page{width:100%;height:100%;display:flex;flex-direction:column;background:var(--bg-canvas);color:var(--fg-1)}.page-hdr{padding:20px 24px 12px;border-bottom:1px solid var(--divider)}.page-hdr h2{font-size:18px;font-weight:700;margin:0}.page-hdr p{font-size:13px;color:var(--fg-3);margin:4px 0 0}.page-bd{flex:1;padding:24px;overflow-y:auto}.stats{display:grid;grid-template-columns:repeat(4,1fr);gap:16px}.stat{text-align:center;padding:24px;background:var(--bg-surface);border:1px solid var(--divider);border-radius:var(--radius-md)}.stat .v{font-size:36px;font-weight:700;color:var(--brand-fg);text-shadow:0 0 16px var(--glow-accent)}.stat div:last-child{font-size:13px;color:var(--fg-3);margin-top:4px}</style>
